-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/bastok/Till_Death_Do_Us_Part.lua"]={["Path"]="scripts/quests/bastok/Till_Death_Do_Us_Part.lua",["SHA256"]="ec64b4dc2deb217766fb8c2ff2a05c4ad4ff90f0724dff76fadd58f7c52e13e8",["Text"]="-----------------------------------\n-- Till Death Do Us Part\n-----------------------------------\n-- Log ID: 1, Quest ID: 18\n-- Romilda : !pos 5.424 4.898 -18.699 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.TILL_DEATH_DO_US_PART)\n\nquest.reward =\n{\n    fame     = 30,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 2000,\n    title    = xi.title.QIJIS_RIVAL,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.FOREVER_TO_HOLD)\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Romilda'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getFameLevel(xi.fameArea.BASTOK) >= 3 then\n                        return quest:progressEvent(128)\n                    else\n                        return quest:event(127)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [128] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Romilda'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.COTTON_GLOVES, 1 } }) then\n                        return quest:progressEvent(129)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [129] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        }\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Trial_Size_Trial_by_Earth.lua"]={["Path"]="scripts/quests/bastok/Trial_Size_Trial_by_Earth.lua",["SHA256"]="4723305f543a9b765743bbda9b9b436627e30f907305e12607e57a0ef245352a",["Text"]="-----------------------------------\n-- Trial-Size Trial by Earth\n-----------------------------------\n-- Log ID: 1, Quest ID: 72\n-- Ferrol : !pos 33.708 6.499 -39.425 236\n-----------------------------------\nlocal tremorsID = zones[xi.zone.CLOISTER_OF_TREMORS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.TRIAL_SIZE_TRIAL_BY_EARTH)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SCROLL_OF_INSTANT_WARP,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 20 and\n                player:getMainJob() == xi.job.SMN and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 2\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            -- NOTE: The below event supports multiple zone references, and which level the Mini Tuning Fork\n            -- drops the Avatar fight to.  1 represents Qucksand Caves, and 20 is the level.\n\n            ['Ferrol'] = quest:progressEvent(297, 0, xi.item.MINI_TUNING_FORK_OF_EARTH, 1, 20),\n\n            onEventFinish =\n            {\n                [297] = function(player, csid, option, npc)\n                    if\n                        option == 1 and\n                        npcUtil.giveItem(player, xi.item.MINI_TUNING_FORK_OF_EARTH)\n                    then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ferrol'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        player:getMainJob() == xi.job.SMN and\n                        trade:hasItemQty(xi.item.MINI_TUNING_FORK_OF_EARTH, 1)\n                    then\n                        return quest:progressEvent(298, 0, xi.item.MINI_TUNING_FORK_OF_EARTH, 1, 20)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if not player:hasItem(xi.item.MINI_TUNING_FORK_OF_EARTH) then\n                        return quest:progressEvent(301, 0, xi.item.MINI_TUNING_FORK_OF_EARTH, 1, 20)\n                    else\n                        return quest:event(251)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [298] = function(player, csid, option, npc)\n                    if option == 1 then\n                        xi.teleport.to(player, xi.teleport.id.CLOISTER_OF_TREMORS)\n                    end\n                end,\n\n                [301] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveItem(player, xi.item.MINI_TUNING_FORK_OF_EARTH)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.CLOISTER_OF_TREMORS] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.TRIAL_SIZE_TRIAL_BY_EARTH then\n                        if not player:hasSpell(xi.magic.spell.TITAN) then\n                            player:addSpell(xi.magic.spell.TITAN)\n                            player:messageSpecial(tremorsID.text.TITAN_UNLOCKED, 0, 0, 1)\n                        end\n\n                        if not player:hasItem(xi.item.SCROLL_OF_INSTANT_WARP) then\n                            npcUtil.giveItem(player, xi.item.SCROLL_OF_INSTANT_WARP)\n                        end\n\n                        quest:complete(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Ferrol'] = quest:event(300):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Trial_by_Earth.lua"]={["Path"]="scripts/quests/bastok/Trial_by_Earth.lua",["SHA256"]="68c81f4da2bad66600d258b7b3ebb8c71e4ca5ea7b0c2d260006a92073234eaf",["Text"]="-----------------------------------\n-- Trial by Earth\n-----------------------------------\n-- Log ID: 1, Quest ID: 61\n-- Juroro : !pos 32 7 -41 236\n-----------------------------------\nlocal portBastokID = zones[xi.zone.PORT_BASTOK]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.TRIAL_BY_EARTH)\n\nquest.reward =\n{\n    fame     = 60,\n    fameArea = xi.fameArea.BASTOK,\n}\n\nlocal rewardItems =\n{\n    [0] = xi.item.TITANS_CUDGEL,\n    [1] = xi.item.EARTH_BELT,\n    [2] = xi.item.EARTH_RING,\n    [3] = xi.item.DOSE_OF_DESERT_LIGHT,\n}\n\nlocal function getRewardMask(player)\n    local rewardMask = 0\n\n    for bitNum, itemId in pairs(rewardItems) do\n        if player:hasItem(itemId) then\n            rewardMask = utils.mask.setBit(rewardMask, bitNum, true)\n        end\n    end\n\n    if player:hasSpell(xi.magic.spell.TITAN) then\n        rewardMask = utils.mask.setBit(rewardMask, 5, true)\n    end\n\n    return rewardMask\nend\n\nlocal function giveQuestReward(player, eventOption)\n    local wasRewarded = true\n\n    if eventOption <= 4 then\n        wasRewarded = npcUtil.giveItem(player, rewardItems[eventOption - 1])\n    elseif eventOption == 5 then\n        npcUtil.giveCurrency(player, 'gil', 10000)\n    elseif eventOption == 6 then\n        player:addSpell(xi.magic.spell.TITAN)\n        player:messageSpecial(portBastokID.text.TITAN_UNLOCKED, 0, 0, 1)\n    end\n\n    return wasRewarded\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 6\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Juroro'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Optional dialogue to start \"Trial by Earth\" if the player has SMN AF1 \"The Puppet Master\" in progress.\n                    local smnAF  = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER) == xi.questStatus.QUEST_ACCEPTED and player:getVar('Quest[2][81]Prog') == 1\n                    local param4 = smnAF and 1 or 0\n                    local param6 = smnAF and xi.item.EARTH_PENDULUM or 0\n                    local param7 = smnAF and 1 or 0\n\n                    return quest:progressEvent(249, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 0, param4, 0, param6, param7)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [249] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_EARTH)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Juroro'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.WHISPER_OF_TREMORS) then\n                        if not player:hasKeyItem(xi.keyItem.TUNING_FORK_OF_EARTH) then\n                            -- Player has failed the BCNM and requires a new Tuning Fork\n\n                            return quest:progressEvent(284, 0, xi.keyItem.TUNING_FORK_OF_EARTH)\n                        else\n                            return quest:event(250, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 1)\n                        end\n                    else\n                        return quest:progressEvent(252, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 1, 0, getRewardMask(player))\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [252] = function(player, csid, option, npc)\n                    if giveQuestReward(player, option) then\n                        quest:complete(player)\n                        player:delKeyItem(xi.keyItem.WHISPER_OF_TREMORS)\n                        quest:setTimedVar(player, 'Timer', NextJstDay())\n                    end\n                end,\n\n                [284] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_EARTH)\n                end,\n            },\n        },\n\n        [xi.zone.CLOISTER_OF_TREMORS] =\n        {\n            onEventFinish =\n            {\n                [32001] = function(player, csid, option, npc)\n                    if player:getLocalVar('battlefieldWin') == xi.battlefield.id.TRIAL_BY_EARTH then\n                        npcUtil.giveKeyItem(player, xi.keyItem.WHISPER_OF_TREMORS)\n                        player:addTitle(xi.title.HEIR_OF_THE_GREAT_EARTH)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                quest:getVar(player, 'Timer') == 0\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Juroro'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Optional dialogue to start \"Trial by Earth\" if the player has SMN AF1 \"The Puppet Master\" in progress.\n                    local smnAF  = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER) == xi.questStatus.QUEST_ACCEPTED and player:getVar('Quest[2][81]Prog') == 1\n                    local param4 = smnAF and 1 or 0\n                    local param6 = smnAF and xi.item.EARTH_PENDULUM or 0\n                    local param7 = smnAF and 1 or 0\n\n                    return quest:progressEvent(249, 0, xi.keyItem.TUNING_FORK_OF_EARTH, 0, param4, 0, param6, param7)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [249] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TRIAL_BY_EARTH)\n\n                        npcUtil.giveKeyItem(player, xi.keyItem.TUNING_FORK_OF_EARTH)\n\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Trust_Bastok.lua"]={["Path"]="scripts/quests/bastok/Trust_Bastok.lua",["SHA256"]="77134aa5698c028fd05467656e33678b9109c2c2095369350fb32fda0691dd2d",["Text"]="-----------------------------------\n-- Trust: Bastok\n-----------------------------------\n-- !addquest 1 92\n-- Clarion Star : !pos 81.478 7.500 -24.169 236\n-- Naji         : !pos 64 -14 -4 237\n-----------------------------------\nlocal metalworksID = zones[xi.zone.METALWORKS]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.TRUST_BASTOK)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.BASTOK_TRUST_PERMIT,\n}\n\nlocal function trustMemoryAyame(player)\n    local memories = 0\n\n    -- 2 - The Three Kingdoms\n    if\n        player:hasCompletedMission(xi.mission.log_id.SANDORIA, xi.mission.id.sandoria.JOURNEY_TO_BASTOK2) or\n        player:hasCompletedMission(xi.mission.log_id.WINDURST, xi.mission.id.windurst.THE_THREE_KINGDOMS_BASTOK2)\n    then\n        memories = memories + 2\n    end\n\n    -- 4 - Where Two Paths Converge\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.WHERE_TWO_PATHS_CONVERGE) then\n        memories = memories + 4\n    end\n\n    -- 8 - The Pirate's Cove\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.THE_PIRATES_COVE) then\n        memories = memories + 8\n    end\n\n    -- 16 - Ayame and Kaede\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.AYAME_AND_KAEDE) then\n        memories = memories + 16\n    end\n\n    -- 32 - Light of Judgement\n    if player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.LIGHT_OF_JUDGMENT) then\n        memories = memories + 32\n    end\n\n    -- 64 - True Strength\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TRUE_STRENGTH) then\n        memories = memories + 64\n    end\n\n    return memories\nend\n\nlocal function trustMemoryIronEater(player)\n    local memories = 0\n    --[[ TODO\n    -- 2 - The Three Kingdoms\n    if player:hasCompletedMission(xi.mission.log_id.SANDORIA, xi.mission.id.sandoria.JOURNEY_TO_BASTOK2) or player:hasCompletedMission(xi.mission.log_id.WINDURST, xi.mission.id.windurst.THE_THREE_KINGDOMS_BASTOK2) then\n        memories = memories + 2\n    end\n    -- 4 - Where Two Paths Converge\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.WHERE_TWO_PATHS_CONVERGE) then\n        memories = memories + 4\n    end\n    -- 8 - The Pirate's Cove\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.THE_PIRATES_COVE) then\n        memories = memories + 8\n    end\n    -- 16 - Ayame and Kaede\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.AYAME_AND_KAEDE) then\n        memories = memories + 16\n    end\n    -- 32 - Light of Judgement\n    if player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.LIGHT_OF_JUDGMENT) then\n        memories = memories + 32\n    end\n    -- 64 - True Strength\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.TRUE_STRENGTH) then\n        memories = memories + 64\n    end\n    ]]--\n\n    -- Incident with Volker and Zeid\n    -- Bring together Mythril Musketeers\n    -- Mastery over the way of the axe\n    -- Galka grieving over the loss of their homeland\n    -- Piece of wood Werei left behind\n    -- Help nenew ties with Raogrimm and Deidogg\n    -- Chose to become an adventurer in the past\n    -- Aht Urhgan, Zazarg\n    -- Republican Iron Medal\n\n    return memories\nend\n\nlocal function trustMemoryNaji(player)\n    local memories = 0\n\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.THE_EMISSARY) then\n        memories = memories + 2\n    end\n\n    if player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_DOORMAN) then\n        memories = memories + 4\n    end\n\n    if player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.LIGHT_OF_JUDGMENT) then\n        memories = memories + 8\n    end\n\n    -- 16 - Chocobo racing\n    --  memories = memories + 16\n\n    return memories\nend\n\nlocal function trustMemoryVolker(player)\n    local memories = 0\n\n    -- 2 - Darkness Rising (Bastok Mission)\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.DARKNESS_RISING) then\n        memories = memories + 2\n    end\n\n    -- 4 - Where Two Paths Converge (Bastok Mission)\n    if player:hasCompletedMission(xi.mission.log_id.BASTOK, xi.mission.id.bastok.WHERE_TWO_PATHS_CONVERGE) then\n        memories = memories + 4\n    end\n\n    -- 8 - Light of Judgment (Aht Urhgan Mission)\n    if player:hasCompletedMission(xi.mission.log_id.TOAU, xi.mission.id.toau.LIGHT_OF_JUDGMENT) then\n        memories = memories + 8\n    end\n\n    -- 16 - Hero's Combat (BCNM)\n    -- if (playervar for Hero's Combat) then\n    --  memories = memories + 16\n    -- end\n\n    return memories\nend\n\nquest.sections =\n{\n    -- Section: Quest available\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 5 and\n                xi.settings.main.ENABLE_TRUST_QUESTS == 1\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Clarion_Star'] =\n            {\n                onTrigger = function(player, npc)\n                    local trustSandoria = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA)\n                    local trustWindurst = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST)\n\n                    -- Haven't started any other trust tutorial quest.\n                    if\n                        trustWindurst == xi.questStatus.QUEST_AVAILABLE and\n                        trustSandoria == xi.questStatus.QUEST_AVAILABLE\n                    then\n                        return quest:progressEvent(434)\n\n                    -- Has finished other trust quest.\n                    elseif\n                        trustWindurst == xi.questStatus.QUEST_COMPLETED or\n                        trustSandoria == xi.questStatus.QUEST_COMPLETED\n                    then\n                        return quest:progressEvent(438)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [434] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.BLUE_INSTITUTE_CARD)\n                    end\n                end,\n\n                [438] = function(player, csid, option, npc)\n                    if option == 2 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.BLUE_INSTITUTE_CARD)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest accepted\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Naji'] =\n            {\n                onTrigger = function(player, npc)\n                    local rank3 = player:getRank(player:getNation()) >= 3 and 1 or 0\n                    local bastokFirstTrust = quest:getVar(player, 'Prog')\n\n                    if\n                        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.TRUST_SANDORIA) == xi.questStatus.QUEST_COMPLETED or\n                        player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.TRUST_WINDURST) == xi.questStatus.QUEST_COMPLETED\n                    then\n                        return quest:progressEvent(984, 0, 0, 0, trustMemoryNaji(player), 0, 0, 0, rank3)\n                    elseif bastokFirstTrust == 0 then\n                        return quest:progressEvent(980, 0, 0, 0, trustMemoryNaji(player), 0, 0, 0, rank3)\n                    elseif bastokFirstTrust == 1 then\n                        return quest:progressEvent(981):oncePerZone()\n                    elseif bastokFirstTrust == 2 then\n                        return quest:progressEvent(982)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [980] = function(player, csid, option, npc)\n                    player:addSpell(xi.magic.spell.NAJI, { silentLog = true })\n                    player:messageSpecial(metalworksID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.NAJI)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [982] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addTitle(xi.title.THE_TRUSTWORTHY)\n                        player:delKeyItem(xi.keyItem.BLUE_INSTITUTE_CARD)\n                        player:messageSpecial(metalworksID.text.KEYITEM_LOST, xi.keyItem.BLUE_INSTITUTE_CARD)\n                        player:messageSpecial(metalworksID.text.CALL_MULTIPLE_ALTER_EGO)\n                    end\n                end,\n\n                [984] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addSpell(xi.magic.spell.NAJI, { silentLog = true })\n                        player:messageSpecial(metalworksID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.NAJI)\n                        player:delKeyItem(xi.keyItem.BLUE_INSTITUTE_CARD)\n                        player:messageSpecial(metalworksID.text.KEYITEM_LOST, xi.keyItem.BLUE_INSTITUTE_CARD)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Clarion_Star'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.BLUE_INSTITUTE_CARD) then\n                        return quest:progressEvent(435)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Ayame'] =\n            {\n                onTrigger = function(player, npc)\n                    local rank3 = player:getRank(player:getNation()) >= 3 and 1 or 0\n\n                    if not player:hasSpell(xi.magic.spell.AYAME) then\n                        return quest:event(985, 0, 0, 0, trustMemoryAyame(player), 0, 0, 0, rank3)\n                    end\n                end,\n            },\n\n            ['Iron_Eater'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasSpell(xi.magic.spell.NAJI) and\n                        player:hasSpell(xi.magic.spell.AYAME) and\n                        player:hasSpell(xi.magic.spell.VOLKER) and\n                        not player:hasSpell(xi.magic.spell.IRON_EATER)\n                    then\n                        return quest:progressEvent(988, 0, 0, 0, trustMemoryIronEater(player)):oncePerZone()\n                    end\n                end,\n            },\n\n            ['Lucius'] =\n            {\n                onTrigger = function(player, npc)\n                    local rank6 = player:getRank(player:getNation()) >= 6 and 1 or 0\n\n                    if not player:hasSpell(xi.magic.spell.VOLKER) then\n                        return quest:event(986, 0, 0, 0, trustMemoryVolker(player), 0, 0, 0, rank6)\n                    end\n                end,\n            },\n\n            ['Naji'] =\n            {\n                onTrigger = function(player, npc)\n                    local rank3 = player:getRank(player:getNation()) >= 3 and 1 or 0\n\n                    if not player:hasSpell(xi.magic.spell.AYAME) then\n                        return quest:progressEvent(983, 0, 0, 0, 0, 0, 0, 0, rank3):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [985] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:addSpell(xi.magic.spell.AYAME, { silentLog = true })\n                        player:messageSpecial(metalworksID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.AYAME)\n                    end\n                end,\n\n                [986] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:addSpell(xi.magic.spell.VOLKER, { silentLog = true })\n                        player:messageSpecial(metalworksID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.VOLKER)\n                    end\n                end,\n\n                [988] = function(player, csid, option, npc)\n                    if option == 2 then\n                        player:addSpell(xi.magic.spell.IRON_EATER, { silentLog = true })\n                        player:messageSpecial(metalworksID.text.YOU_LEARNED_TRUST, 0, xi.magic.spell.IRON_EATER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Clarion_Star'] = quest:progressEvent(436),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Vengeful_Wrath.lua"]={["Path"]="scripts/quests/bastok/Vengeful_Wrath.lua",["SHA256"]="22163d0e71370b817a5acfbc6c474d628e940bd276e4c9b605739ad05ecf17fe",["Text"]="-----------------------------------\n-- Vengeful Wrath\n-----------------------------------\n-- Log ID: 1, Quest ID: 32\n-- Goraow : !pos 38 .1 14 234\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.VENGEFUL_WRATH)\n\nquest.reward =\n{\n    fame     = 16,\n    fameArea = xi.fameArea.BASTOK,\n    gil      = 900,\n    title    = xi.title.AVENGER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 3\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Goraow'] = quest:progressEvent(106),\n\n            onEventFinish =\n            {\n                [106] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status ~= xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Goraow'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.QUADAV_HELM, 1 } }) then\n                        return quest:progressEvent(107)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [107] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/WAR_AF1_The_Doorman.lua"]={["Path"]="scripts/quests/bastok/WAR_AF1_The_Doorman.lua",["SHA256"]="efd7887704fa76b84b1033df36778b2c695b0fe009e76266503a99ac847f95c2",["Text"]="-----------------------------------\n-- The Doorman\n-----------------------------------\n-- Log ID: 1, Quest ID: 54\n-- Phara         : !pos 75 0 -80 234\n-- Hide Flap (1) : !pos 293 3 -213 149\n-- Naji          : !pos 64 -14 -4 237\n-----------------------------------\nlocal davoiID = zones[xi.zone.DAVOI]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_DOORMAN)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.RAZOR_AXE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.WAR and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Phara'] = quest:progressEvent(151),\n\n            onEventFinish =\n            {\n                [151] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.DAVOI] =\n        {\n            ['Hide_Flap_1'] =\n            {\n                onTrigger = function(player, npc)\n                    player:messageSpecial(davoiID.text.FIND_ORC_TENT)\n\n                    if player:checkDistance(npc) > 1 then\n                        return quest:messageSpecial(davoiID.text.CLOSER_TO_SEARCH)\n                    elseif\n                        not GetMobByID(davoiID.mob.GAVOTVUT):isAlive() and\n                        not GetMobByID(davoiID.mob.BARAKBOK):isAlive()\n                    then\n                        return quest:progressEvent(110)\n                    else\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [110] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        return\n                    end\n\n                    if player:hasKeyItem(xi.keyItem.SWORD_GRIP_MATERIAL) then\n                        player:messageSpecial(davoiID.text.YOU_FIND_NOTHING)\n                        return\n                    end\n\n                    if quest:getLocalVar(player, 'nmKilled') == 3 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SWORD_GRIP_MATERIAL)\n                        return\n                    end\n\n                    if\n                        not GetMobByID(davoiID.mob.GAVOTVUT):isSpawned() and\n                        not GetMobByID(davoiID.mob.BARAKBOK):isSpawned()\n                    then\n                        player:messageSpecial(davoiID.text.YOU_FIND_NOTHING)\n                        SpawnMob(davoiID.mob.GAVOTVUT):updateClaim(player)\n                        SpawnMob(davoiID.mob.BARAKBOK):updateClaim(player)\n                        quest:setLocalVar(player, 'nmClaimed', 1)\n                        return\n                    end\n                end,\n            },\n\n            ['Barakbok'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getLocalVar(player, 'nmClaimed') == 1 then\n                        local nmStatus = quest:getLocalVar(player, 'nmKilled')\n\n                        quest:setLocalVar(player, 'nmKilled', utils.mask.setBit(nmStatus, 0, true))\n                    end\n                end,\n            },\n\n            ['Gavotvut'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getLocalVar(player, 'nmClaimed') == 1 then\n                        local nmStatus = quest:getLocalVar(player, 'nmKilled')\n\n                        quest:setLocalVar(player, 'nmKilled', utils.mask.setBit(nmStatus, 1, true))\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Phara'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SWORD_GRIP_MATERIAL) then\n                        return quest:progressEvent(152)\n                    elseif\n                        quest:getVar(player, 'Prog') == 1 and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(153)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [152] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.SWORD_GRIP_MATERIAL)\n\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [153] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.YASINS_SWORD)\n\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Naji'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.YASINS_SWORD) then\n                        return quest:progressEvent(750)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [750] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.YASINS_SWORD)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/WAR_AF2_The_Talekeepers_Truth.lua"]={["Path"]="scripts/quests/bastok/WAR_AF2_The_Talekeepers_Truth.lua",["SHA256"]="bb0c9441b2879f2a2201b8aa811d1a406b333f7449bd2f9a69c0e468d8d5e397",["Text"]="-----------------------------------\n-- The Talekeeper's Truth\n-----------------------------------\n-- Log ID: 1, Quest ID: 55\n-- Phara         : !pos 75 0 -80 234\n-- Deidogg       : !pos -13 7 29 234\n-- qm_talekeeper : !pos 15 -31 -94 143\n-----------------------------------\nlocal palboroughMinesID = zones[xi.zone.PALBOROUGH_MINES]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_TRUTH)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.FIGHTERS_CALLIGAE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_DOORMAN) and\n                player:getMainJob() == xi.job.WAR and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Deidogg'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(160)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(161)\n                    end\n                end,\n            },\n\n            ['Phara'] = quest:progressEvent(154),\n\n            onEventFinish =\n            {\n                [154] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [160] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [161] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 0)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Deidogg'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress == 0 and\n                        npcUtil.tradeMatches(trade, { { xi.item.MOTTLED_QUADAV_EGG, 1 } })\n                    then\n                        return quest:progressEvent(162)\n                    elseif\n                        questProgress == 1 and\n                        npcUtil.tradeMatches(trade, { { xi.item.PARASITE_SKIN, 1 } })\n                    then\n                        return quest:progressEvent(164)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:event(163)\n                    elseif questProgress == 2 then\n                        if quest:getVar(player, 'Timer') <= VanadielUniqueDay() then\n                            return quest:progressEvent(165)\n                        else\n                            return quest:event(166)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [162] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [164] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n\n                [165] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_GIFT, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_GIFT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PALBOROUGH_MINES] =\n        {\n            ['qm_talekeeper'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.popFromQM(player, npc, palboroughMinesID.mob.NI_GHU_NESTFENDER, { hide = 0 })\n                    then\n                        return quest:messageSpecial(palboroughMinesID.text.SENSE_OF_FOREBODING)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Deidogg'] = quest:event(166):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/WAR_AF3_The_Talekeepers_Gift.lua"]={["Path"]="scripts/quests/bastok/WAR_AF3_The_Talekeepers_Gift.lua",["SHA256"]="81d64994da9a5f4ab1fa86a29a8f6c7e53563dcbde82ef07b8f0ccaa4765efaf",["Text"]="-----------------------------------\n-- The Talekeeper's Gift\n-----------------------------------\n-- Log ID: 1, Quest ID: 56\n-- Deidogg       : !pos -13 7 29 234\n-- Detzo         : !pos 5.365 6.999 9.891 234\n-- qm_talekeeper : !pos 211 4 -79 127\n-----------------------------------\nlocal behemothsDominionID = zones[xi.zone.BEHEMOTHS_DOMINION]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_GIFT)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.FIGHTERS_LORICA,\n    title    = xi.title.PARAGON_OF_WARRIOR_EXCELLENCE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_TRUTH) and\n                player:getMainJob() == xi.job.WAR and\n                player:getMainLvl() >= xi.settings.main.AF3_QUEST_LEVEL and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                not quest:getMustZone(player)\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Deidogg'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 2 and\n                        npcUtil.tradeMatches(trade, { { xi.item.GINGER_COOKIE, 1 } })\n                    then\n                        return quest:progressEvent(172)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(170)\n                    end\n                end,\n            },\n\n            ['Detzo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(171)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [170] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [171] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [172] = function(player, csid, option, npc)\n                    player:tradeComplete()\n\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 0)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BEHEMOTHS_DOMINION] =\n        {\n            ['qm_talekeeper'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') ~= 7 and\n                        not GetMobByID(behemothsDominionID.mob.TALEKEEPERS_GIFT_OFFSET + 0):isSpawned() and\n                        not GetMobByID(behemothsDominionID.mob.TALEKEEPERS_GIFT_OFFSET + 1):isSpawned() and\n                        not GetMobByID(behemothsDominionID.mob.TALEKEEPERS_GIFT_OFFSET + 2):isSpawned()\n                    then\n                        player:messageSpecial(behemothsDominionID.text.THERE_ARE_SYMBOLS)\n                        return quest:progressEvent(100)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    if option == 0 then\n                        SpawnMob(behemothsDominionID.mob.TALEKEEPERS_GIFT_OFFSET + 0):updateClaim(player) -- Picklix_Longindex\n                        SpawnMob(behemothsDominionID.mob.TALEKEEPERS_GIFT_OFFSET + 1):updateEnmity(player) -- Moxnix_Nightgoggle\n                        SpawnMob(behemothsDominionID.mob.TALEKEEPERS_GIFT_OFFSET + 2):updateEnmity(player) -- Doglix_Muttsnout\n\n                        return player:messageSpecial(behemothsDominionID.text.YOU_HEAR_A_NOISE)\n                    end\n                end,\n            },\n\n            ['Doglix_Muttsnout'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVarBit(player, 'Prog', 0)\n                end,\n            },\n\n            ['Moxnix_Nightgoggle'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVarBit(player, 'Prog', 1)\n                end,\n            },\n\n            ['Picklix_Longindex'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    quest:setVarBit(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.QUFIM_ISLAND] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.BEHEMOTHS_DOMINION and\n                    quest:getVar(player, 'Prog') == 7\n                then\n                    return 100\n                end\n            end,\n\n            onEventFinish =\n            {\n                [100] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Welcome_to_Bastok.lua"]={["Path"]="scripts/quests/bastok/Welcome_to_Bastok.lua",["SHA256"]="06b17bdcef4e8db842c8145cb68d5604d1dfab49f7c3e02b07901669571f6d9a",["Text"]="-----------------------------------\n-- Welcome to Bastok\n-----------------------------------\n-- Log ID: 1, Quest ID: 2\n-- Powhatan   : !pos -152.135 -7.48 19.014 236\n-- Bartolomeo : !pos -84.967 1.896 -18.679 236\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.WELCOME_TO_BASTOK)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SPATHA,\n    title    = xi.title.BASTOK_WELCOMING_COMMITTEE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Powhatan'] = quest:progressEvent(50),\n\n            onEventFinish =\n            {\n                [50] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            ['Powhatan'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(51)\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(53)\n                    end\n                end,\n            },\n\n            ['Bartolomeo'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getEquipID(xi.slot.SUB) == xi.item.SHELL_SHIELD and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(52)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [52] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [53] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/bastok/Wish_Upon_a_Star.lua"]={["Path"]="scripts/quests/bastok/Wish_Upon_a_Star.lua",["SHA256"]="ecf5fb143be7b51e234294c08e8bff7e3e8ac44c30539cc78359e82ee5daf87e",["Text"]="-----------------------------------\n-- Wish Upon a Star\n-----------------------------------\n-- Log ID: 1, Quest ID: 64\n-- Zacc   : !pos -255.709 -13 -91.379 235\n-- Malene : !pos -173 -5 64 235\n-- Enu    : !pos -253.673 -13 -92.326 235\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.BASTOK, xi.quest.id.bastok.WISH_UPON_A_STAR)\n\nquest.reward =\n{\n    fame     = 50,\n    fameArea = xi.fameArea.BASTOK,\n    item     = { { xi.item.BAG_OF_CACTUS_STEMS, 4 } },\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getFameLevel(xi.fameArea.BASTOK) >= 5\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Enu'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(332)\n                    end\n                end,\n            },\n\n            ['Malene'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(330)\n                    end\n                end,\n            },\n\n            ['Zacc'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(329)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [329] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [330] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [332] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.YUHTUNGA_JUNGLE] =\n        {\n            ['Logging_Point'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasItem(xi.item.FALLEN_STAR) and\n                        npcUtil.tradeMatches(trade, { { xi.item.HATCHET, 1 } }) -- TODO: This should use actual HELM system.\n                    then\n                        if npcUtil.giveItem(player, xi.item.FALLEN_STAR, { silent = true, fromTrade = true }) then\n                            player:tradeComplete()\n                            return quest:progressEvent(205, xi.item.FALLEN_STAR)\n                        end\n                    end\n                end\n            },\n        },\n\n        [xi.zone.YHOATOR_JUNGLE] =\n        {\n            ['Logging_Point'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasItem(xi.item.FALLEN_STAR) and\n                        npcUtil.tradeMatches(trade, { { xi.item.HATCHET, 1 } }) -- TODO: This should use actual HELM system.\n                    then\n                        if npcUtil.giveItem(player, xi.item.FALLEN_STAR, { silent = true, fromTrade = true }) then\n                            player:tradeComplete()\n                            return quest:progressEvent(10, xi.item.FALLEN_STAR)\n                        end\n                    end\n                end\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Enu'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeMatches(trade, { { xi.item.FALLEN_STAR, 1 } }) then\n                        local isNight = VanadielTOTD() == xi.time.NIGHT or VanadielTOTD() == xi.time.MIDNIGHT\n\n                        if\n                            player:getWeather() == xi.weather.NONE and\n                            isNight\n                        then\n                            return quest:progressEvent(334)\n                        else\n                            return quest:event(337)\n                        end\n                    end\n                end,\n\n                onTrigger = quest:event(333),\n            },\n\n            onEventFinish =\n            {\n                [334] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:tradeComplete()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Enu']  = quest:event(335):replaceDefault(),\n            ['Zacc'] = quest:event(336):replaceDefault(),\n        },\n    }\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/A_Little_Knowledge.lua"]={["Path"]="scripts/quests/crystalWar/A_Little_Knowledge.lua",["SHA256"]="edaabd592d7f094cd06f8bb5c72e34df55719d1d040b857d2a2fae68f1cd546d",["Text"]="-----------------------------------\n-- A Little Knowledge\n-----------------------------------\n-- !addquest 7 6\n-- Erlene : !pos 376.936 -39.999 17.914 175\n-----------------------------------\nlocal eldiemeSID = zones[xi.zone.THE_ELDIEME_NECROPOLIS_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.A_LITTLE_KNOWLEDGE)\n\nquest.reward =\n{\n    keyItem = { xi.keyItem.GRIMOIRE, xi.keyItem.JOB_GESTURE_SCHOLAR },\n    title   = xi.title.SCHULTZ_SCHOLAR,\n}\n\nlocal validMageJobs = set{ xi.job.BLM, xi.job.RDM, xi.job.SMN, xi.job.BLU }\n\nlocal tuckerEventFinish = function(player, csid, option, npc)\n    local numAwarded = quest:getLocalVar(player, 'numAwarded')\n\n    if npcUtil.giveItem(player, { { xi.item.SHEET_OF_VELLUM, numAwarded } }) then\n        player:confirmTrade()\n        quest:incrementVar(player, 'Option', 1)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= xi.settings.main.ADVANCED_JOB_LEVEL\n        end,\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] = quest:progressEvent(10, 1),\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CRAWLERS_NEST_S] =\n        {\n            ['Tucker'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local questOption = quest:getVar(player, 'Option')\n\n                    -- Note: The number of vellum rewarded per trade is determined by the number of stacks traded, so\n                    -- the below condition checks if the player is in the correct state, has only rolanberries in the trade\n                    -- container, and has at _least_ one stack in the trade.  The minimum one stack needs to be verified.\n\n                    -- In addition, need to determine if partial stacks are consumed and implement that if needed.\n\n                    if\n                        questOption >= 1 and\n                        questOption <= 3 and\n                        trade:getItemQty(xi.item.ROLANBERRY) >= 12 and\n                        trade:hasItemQty(xi.item.ROLANBERRY, trade:getItemCount())\n                    then\n                        local numAwardedVellum = math.min(4, math.floor(trade:getItemCount() / 12))\n\n                        trade:confirmItem(xi.item.ROLANBERRY, numAwardedVellum * 12)\n                        quest:setLocalVar(player, 'numAwarded', numAwardedVellum)\n\n                        if questOption == 1 then\n                            return quest:progressEvent(8)\n                        elseif questOption == 2 then\n                            return quest:progressEvent(10)\n                        elseif questOption == 3 then\n                            return quest:progressEvent(11)\n                        end\n                    else\n                        return quest:progressEvent(14)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        local questOption = quest:getVar(player, 'Option')\n\n                        if questOption == 0 then\n                            return quest:progressEvent(6)\n                        elseif questOption == 1 then\n                            return quest:event(7)\n                        elseif questOption <= 3 then\n                            return quest:event(9)\n                        elseif questOption == 4 then\n                            return quest:event(12)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [8]  = tuckerEventFinish,\n                [10] = tuckerEventFinish,\n                [11] = tuckerEventFinish,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.SHEET_OF_VELLUM, 12 } })\n                    then\n                        local isMageJob = validMageJobs[player:getMainJob()] and 1 or 0\n\n                        return quest:progressEvent(12, isMageJob)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(11)\n                    elseif questProgress == 1 then\n                        if\n                            player:hasStatusEffect(xi.effect.MANAFONT) or\n                            player:hasStatusEffect(xi.effect.CHAINSPELL) or\n                            player:hasStatusEffect(xi.effect.ASTRAL_FLOW) or\n                            player:hasStatusEffect(xi.effect.AZURE_LORE)\n                        then\n                            return quest:progressEvent(14)\n                        else\n                            return quest:event(13)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [14] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:unlockJob(xi.job.SCH)\n                        player:messageSpecial(eldiemeSID.text.YOU_CAN_NOW_BECOME_A_SCHOLAR)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getMainJob() == xi.job.SCH and\n                        player:getMainLvl() >= 5 and\n                        not player:hasSpell(xi.magic.spell.EMBRAVA) and\n                        not player:hasSpell(xi.magic.spell.KAUSTRA)\n                    then\n                        return quest:progressEvent(47)\n                    else\n                        return quest:event(15):replaceDefault()\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [47] = function(player, csid, option, npc)\n                    player:addSpell(xi.magic.spell.EMBRAVA, { silentLog = true })\n                    player:addSpell(xi.magic.spell.KAUSTRA, { silentLog = true })\n                    player:messageSpecial(eldiemeSID.text.YOU_LEARN_EMBRAVA_AND_KAUSTRA)\n                end,\n            }\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Hammering_Hearts.lua"]={["Path"]="scripts/quests/crystalWar/Hammering_Hearts.lua",["SHA256"]="95994e6575f034385b38846b75263705a9a6fb252ae10cf7e3be724cf8ad505f",["Text"]="-----------------------------------\n-- Hammering Hearts\n-- !addquest 7 14\n-- Scarred Shark: !pos -233.989 -2.000 67.638 87\n-- HEAVY_QUADAV_CHESTPLATE: !additem 2504\n-- HEAVY_QUADAV_BACKPLATE: !additem 2505\n-- TRAINEE_HAMMER: !additem 18855\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HAMMERING_HEARTS)\n\nquest.reward =\n{\n    item = xi.item.TRAINEE_HAMMER,\n}\n\nquest.sections =\n{\n    -- Section: Talk to Scarred Shark in Bastok Markets (S) at (G-5) for a cutscene.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Scarred_Shark'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(40)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [40] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- 0: Trade a Heavy Quadav Backplate and a Heavy Quadav Chestplate to Scarred Shark.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Scarred_Shark'] =\n            {\n                -- Reminder\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(43)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.HEAVY_QUADAV_CHESTPLATE, xi.item.HEAVY_QUADAV_BACKPLATE }) then\n                        return quest:progressEvent(41)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [41] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 1)\n                    player:setLocalVar('Quest[7][14]NeedToZone', 1)\n                end,\n            },\n        },\n    },\n\n    -- 1: Zone, then talk to Scarred Shark again for a final cutscene and your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Scarred_Shark'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getLocalVar('Quest[7][14]NeedToZone') == 1 then\n                        return quest:progressEvent(44)\n                    else\n                        return quest:progressEvent(42)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [42] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    -- Section: Quest completed. New default text\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Scarred_Shark'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(45):replaceDefault()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Her_Memories_Azure_Footfalls.lua"]={["Path"]="scripts/quests/crystalWar/Her_Memories_Azure_Footfalls.lua",["SHA256"]="d3b1ad758f26f9d5dc1f623f21adf1c3ce80922affcdbd385e9efb46519854b1",["Text"]="-----------------------------------\n-- Her Memories: Azure Footfalls\n-----------------------------------\n-- !addquest 7 70\n-- Adelbrecht       : !pos -325.8 -12.6 -77.0 87\n-- Gebhardt         : !pos 206.3 -20.8 669.1 88\n-- Roderich         : !pos -400.0 40.0 -90.4 88\n-- Barricade        : !pos -515.0 38.0 583.3 88\n-----------------------------------\nrequire('scripts/missions/wotg/helpers')\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_AZURE_FOOTFALLS)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LARGE_MEMORY_FRAGMENT4,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.WOTG) == xi.mission.id.wotg.HER_MEMORIES and\n                player:getCampaignAllegiance() == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Adelbrecht'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(359)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.NORTH_GUSTABERG_S and\n                    quest:getVar(player, 'Prog') == 0\n                then\n                    return 358\n                end\n            end,\n\n            onEventFinish =\n            {\n                [358] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [359] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['Gebhardt'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(14)\n                    end\n                end,\n            },\n\n            ['Roderich'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(15)\n                    end\n                end,\n            },\n\n            ['Barricade'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(16)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [14] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [15] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [16] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Adelbrecht'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(360)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [360] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    xi.wotg.helpers.checkMemoryFragments(player)\n                end,\n            },\n        },\n\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Her_Memories_Carnelian_Footfalls.lua"]={["Path"]="scripts/quests/crystalWar/Her_Memories_Carnelian_Footfalls.lua",["SHA256"]="f5348a2246899d1d5d601444d20d436deba6677c597524e9f1eec7c098bb27f5",["Text"]="-----------------------------------\n-- Her Memories: Carnelian Footfalls\n-----------------------------------\n-- !addquest 7 69\n-- Mainchelite : !pos -16 1 -30 80\n-- qm3         : !pos 312.821 -30.495 -67.15 81\n-- qm4         : !pos 541.425 -49.83 178.563 81\n-- qm5         : !pos 380.015 -26.5 -22.525 81\n-----------------------------------\nrequire('scripts/missions/wotg/helpers')\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_CARNELIAN_FOOTFALLS)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LARGE_MEMORY_FRAGMENT4,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.WOTG) == xi.mission.id.wotg.HER_MEMORIES and\n                player:getCampaignAllegiance() == 1\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Mainchelite'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(171, 80, 90)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.EAST_RONFAURE_S and\n                    quest:getVar(player, 'Prog') == 0\n                then\n                    return 170\n                end\n            end,\n\n            onEventFinish =\n            {\n                [170] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [171] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Mainchelite'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 7 then\n                        return quest:progressEvent(172, 1, 23, 1749)\n                    else\n                        return quest:event(173, 80, 3, 2964):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [172] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.wotg.helpers.checkMemoryFragments(player)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.EAST_RONFAURE_S] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 0) then\n                        return quest:progressEvent(13, 81, 0, 1756, 0, 0, 0, 3, 4095)\n                    else\n                        return quest:event(4)\n                    end\n                end,\n            },\n\n            ['qm4'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 1) then\n                        return quest:progressEvent(14, 81, 1, 1756, 0, 0, 0, 3, 4095)\n                    else\n                        return quest:event(5)\n                    end\n                end,\n            },\n\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    if not quest:isVarBitsSet(player, 'Option', 2) then\n                        return quest:progressEvent(15, 81, 0, 1756, 0, 0, 0, 3, 4095)\n                    else\n                        return quest:event(6)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.SOUTHERN_SAN_DORIA_S and\n                    quest:getVar(player, 'Prog') == 1\n                then\n                    return 12\n                end\n            end,\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 0)\n                end,\n\n                [14] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 1)\n                end,\n\n                [15] = function(player, csid, option, npc)\n                    quest:setVarBit(player, 'Option', 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Her_Memories_Homecoming_Queen.lua"]={["Path"]="scripts/quests/crystalWar/Her_Memories_Homecoming_Queen.lua",["SHA256"]="0c7cd4a3955e9462aa815003e4d74593540856f1b9a6d93f49b19df887672c6a",["Text"]="-----------------------------------\n-- Her Memories: Homecoming Queen\n-----------------------------------\n-- !addquest 7 64\n-- Thierride  : !pos -67 -5 -28 232\n-- Amaura     : !pos -84.367 -6.949 91.148 230\n-- Abioleget  : !pos 128.771 0.000 118.538 231\n-- Bertenont  : !pos -165 0.1 226 231\n-- Halver     : !pos 2 0.1 0.1 233\n-- Gravestone : !pos 149.728 -5.109 -395.121 105\n-----------------------------------\nrequire('scripts/missions/wotg/helpers')\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_HOMECOMING_QUEEN)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LARGE_MEMORY_FRAGMENT1,\n}\n\nlocal subQuestData =\n{\n    [793] = { xi.quest.id.crystalWar.HER_MEMORIES_OLD_BEAN,          xi.keyItem.TINY_MEMORY_FRAGMENT1 },\n    [870] = { xi.quest.id.crystalWar.HER_MEMORIES_THE_FAUX_PAS,      xi.keyItem.TINY_MEMORY_FRAGMENT2 },\n    [6  ] = { xi.quest.id.crystalWar.HER_MEMORIES_THE_GRAVE_RESOLVE, xi.keyItem.TINY_MEMORY_FRAGMENT3 },\n}\n\nlocal function handleQuestCompletion(player, csid, option, npc)\n    local ID = zones[player:getZoneID()]\n    local numKeyItems = 0\n\n    for _, questData in pairs(subQuestData) do\n        if player:hasKeyItem(questData[2]) then\n            numKeyItems = numKeyItems + 1\n        end\n    end\n\n    player:completeQuest(xi.questLog.CRYSTAL_WAR, subQuestData[csid][1])\n\n    if numKeyItems < 2 then\n        player:messageName(ID.text.FRAGMENT_FAR_TOO_SMALL, nil, subQuestData[csid][2])\n        npcUtil.giveKeyItem(player, subQuestData[csid][2])\n    else\n        player:messageSpecial(ID.text.FRAGMENTS_MELD, xi.keyItem.LARGE_MEMORY_FRAGMENT1)\n\n        for _, questData in pairs(subQuestData) do\n            player:delKeyItem(questData[2])\n        end\n\n        if quest:complete(player) then\n            xi.wotg.helpers.checkMemoryFragments(player)\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.WOTG) == xi.mission.id.wotg.HER_MEMORIES\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.EAST_RONFAURE then\n                    return 957\n                end\n            end,\n\n            onEventFinish =\n            {\n                [957] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Her Memories: Old Bean\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_OLD_BEAN) ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Thierride'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog1')\n\n                    if questProgress == 0 then\n                        if not player:hasKeyItem(xi.keyItem.THIERRIDES_BEAN_CREATION) then\n                            return quest:progressEvent(792)\n                        else\n                            return quest:event(794):oncePerZone()\n                        end\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(793)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [792] = function(player, csid, option, npc)\n                    player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_OLD_BEAN)\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.THIERRIDES_BEAN_CREATION)\n                end,\n\n                [793] = handleQuestCompletion,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Amaura'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.THIERRIDES_BEAN_CREATION) then\n                        return quest:progressEvent(958, 650067949, 0, 5, 0, 156286100, 100000, 4095, 131073)\n                    elseif quest:getVar(player, 'Prog1') == 1 then\n                        return quest:event(959):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [958] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.THIERRIDES_BEAN_CREATION)\n\n                    quest:setVar(player, 'Prog1', 1)\n                end,\n            },\n        },\n    },\n\n    -- Her Memories: The Faux Pas\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_THE_FAUX_PAS) ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            ['Abioleget'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog2') == 0 then\n                        return quest:progressEvent(869)\n                    else\n                        return quest:event(871):oncePerZone()\n                    end\n                end,\n            },\n\n            ['Bertenont'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog2') == 1 then\n                        return quest:progressEvent(870)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [869] = function(player, csid, option, npc)\n                    player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_THE_FAUX_PAS)\n\n                    quest:setVar(player, 'Prog2', 1)\n                end,\n\n                [870] = handleQuestCompletion,\n            },\n        },\n    },\n\n    -- Her Memories: The Grave Resolve\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_THE_GRAVE_RESOLVE) ~= xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.CHATEAU_DORAGUILLE] =\n        {\n            ['Halver'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog3') == 0 then\n                        return quest:progressEvent(571, 65, 23, 2964, 100000, 233714167, 0, 1, 0)\n                    else\n                        return quest:event(572, 69, 23, 2964, 100000, 233714167, 0, 1, 0):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [571] = function(player, csid, option, npc)\n                    player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_THE_GRAVE_RESOLVE)\n\n                    quest:setVar(player, 'Prog3', 1)\n                end,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS] =\n        {\n            ['Weathered_Gravestone'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.LILAC) and\n                        quest:getVar(player, 'Prog3') == 2\n                    then\n                        player:confirmTrade()\n\n                        return quest:progressEvent(6, 119, 300, 200, 100, 0, 0, 558716, 0)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog3') >= 1 then\n                        return quest:progressEvent(5, 105, 0, 0, 0, 43, 0, 558716, 0)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog3', 2)\n                end,\n\n                [6] = handleQuestCompletion,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Her_Memories_Of_Malign_Maladies.lua"]={["Path"]="scripts/quests/crystalWar/Her_Memories_Of_Malign_Maladies.lua",["SHA256"]="784027026972d1405b18680a57fcdabd0cef5a22ddad749601faee09bd2b5625",["Text"]="-----------------------------------\n-- Her Memories: Of Malign Maladies\n-----------------------------------\n-- !addquest 7 72\n-- Amaura       : !pos -84.367 -6.949 91.148 230\n-- Monberaux    : !pos -42 0 -2 244\n-- Library Book : !pos -16.17 -6.25 112.289 238\n-- Fey Blossoms : !pos -141.312 -6.75 564.417 89\n-- Raustigne    : !pos 3.979 -1.999 44.456 80\n-----------------------------------\nrequire('scripts/missions/wotg/helpers')\n-----------------------------------\nlocal graubergID = zones[xi.zone.GRAUBERG_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_OF_MALIGN_MALADIES)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LARGE_MEMORY_FRAGMENT2,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.WOTG) == xi.mission.id.wotg.HER_MEMORIES\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Amaura'] = quest:progressEvent(955, 649992904, 0, 0, 0, 156286100, 19935, 0, 4),\n\n            onEventFinish =\n            {\n                [955] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Amaura'] = quest:event(956, 649993042, 0, 27830, 94060, 0, 0, 0, 0):oncePerZone(),\n        },\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Monberaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(10190, 244, 1, 40, 0, 62914449, 41076209, 4095, 131105)\n                    else\n                        return quest:event(10191, 244, 1, 255, 0, 65339391, 27831, 4095, 131105)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10190] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Library_book3'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(1017, 650060514, 0, 0, 0, 110, 6312479, 4095, 128)\n                    elseif questProgress == 2 then\n                        return quest:event(1018, 650060691, 0, 0, 0, 65863679, 4104166, 4095, 4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1017] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Fey_Blossoms'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.PHILOSOPHERS_STONE) and\n                        quest:getVar(player, 'Prog') == 2\n                    then\n                        return quest:progressEvent(30, 89, 23, 2964, 56, 0, 6029313, 0, 0)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:messageSpecial(graubergID.text.SUITABLE_PLACE_TO_SOAK, xi.item.PHILOSOPHERS_STONE)\n                    elseif\n                        questProgress == 3 and\n                        not player:hasKeyItem(xi.keyItem.FEY_STONE)\n                    then\n                        if quest:getVar(player, 'Timer') <= VanadielUniqueDay() then\n                            return quest:progressEvent(32, 89, 6, 0, 56, 0, 6029328, 0, 0)\n                        else\n                            return quest:event(31, 89, 23, 2964, 56, 0, 6029313, 0, 0)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [30] = function(player, csid, option, npc)\n                    player:confirmTrade()\n\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n\n                [32] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FEY_STONE)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Raustigne'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.FEY_STONE) then\n                        return quest:progressEvent(169, 80, 23, 1756, 0, 67108863, 85453257, 3903, 131140)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [169] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.wotg.helpers.checkMemoryFragments(player)\n                        player:delKeyItem(xi.keyItem.FEY_STONE)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Her_Memories_Operation_Cupid.lua"]={["Path"]="scripts/quests/crystalWar/Her_Memories_Operation_Cupid.lua",["SHA256"]="2ad75c18c0cf85971005cd5b84d62d77364c77b875b77c60069c5e9e5dc1620d",["Text"]="-----------------------------------\n-- Her Memories: Operation Cupid\n-----------------------------------\n-- !addquest 7 68\n-- Bulwark Gate : !pos -447.174 -1.831 342.417 98\n-- Leadavox     : !pos 206 -32 316 83\n-----------------------------------\nrequire('scripts/missions/wotg/helpers')\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HER_MEMORIES_OPERATION_CUPID)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.LARGE_MEMORY_FRAGMENT3,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getCurrentMission(xi.mission.log_id.WOTG) == xi.mission.id.wotg.HER_MEMORIES\n        end,\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.JUGNER_FOREST_S then\n                    return 23\n                end\n            end,\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SAUROMUGUE_CHAMPAIGN_S] =\n        {\n            ['Bulwark_Gate'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if player:hasKeyItem(xi.keyItem.POT_OF_MARTIAL_RELISH) then\n                        return quest:progressEvent(13)\n                    elseif questProgress == 0 then\n                        return quest:progressEvent(11)\n                    elseif questProgress == 2 then\n                        return quest:event(14):oncePerZone()\n                    else\n                        return quest:event(12):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.POT_OF_MARTIAL_RELISH)\n                end,\n            },\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['Leadavox'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        not player:hasKeyItem(xi.keyItem.POT_OF_MARTIAL_RELISH) and\n                        npcUtil.tradeHasExactly(trade, { xi.item.BOTTLE_OF_RICE_VINEGAR, xi.item.JAR_OF_GROUND_WASABI, xi.item.SPRIG_OF_HOLY_BASIL }) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(4)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.POT_OF_MARTIAL_RELISH) then\n                        return quest:event(5):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.POT_OF_MARTIAL_RELISH)\n                end,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.ROLANBERRY_FIELDS_S and\n                    quest:getVar(player, 'Prog') == 2\n                then\n                    return 24\n                end\n            end,\n\n            onEventFinish =\n            {\n                [24] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.wotg.helpers.checkMemoryFragments(player)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Lost_in_Translocation.lua"]={["Path"]="scripts/quests/crystalWar/Lost_in_Translocation.lua",["SHA256"]="b4f5ad410a7984e9134588144749c92b981fcd885612ba8f0852b2a3ba2291f5",["Text"]="-----------------------------------\n-- Lost in Translocation\n-----------------------------------\n-- !addquest 7 0\n-- Thorben     : !pos 175.346 8.038 -419.244 84\n-- Erik        : !pos 258.643 -33.249 99.901 175\n-- Gravestone  : !pos 254.428 -32.999 20.001 175\n-- Sarcophagus : !pos 336.594 -33.500 -56.728 175\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.LOST_IN_TRANSLOCATION)\n\nquest.reward =\n{\n    gil     = 2000,\n    exp     = 2000,\n    keyItem = xi.keyItem.MAP_OF_GRAUBERG,\n}\n\nlocal mapKeyItems =\n{\n    xi.keyItem.LEFT_MAP_PIECE,\n    xi.keyItem.MIDDLE_MAP_PIECE,\n    xi.keyItem.RIGHT_MAP_PIECE,\n}\n\nlocal function getNumMapPieces(player)\n    local numKeyItems = 0\n\n    for _, keyItem in ipairs(mapKeyItems) do\n        if player:hasKeyItem(keyItem) then\n            numKeyItems = numKeyItems + 1\n        end\n    end\n\n    return numKeyItems\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Thorben'] = quest:progressEvent(103),\n\n            onEventFinish =\n            {\n                [103] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Thorben'] =\n            {\n                onTrigger = function(player, npc)\n                    local numMapPieces = getNumMapPieces(player)\n\n                    if numMapPieces == 3 then\n                        return quest:progressEvent(107)\n                    elseif quest:getVar(player, 'Option') == 1 then\n                        return quest:event(106)\n                    elseif numMapPieces > 0 then\n                        return quest:progressEvent(105)\n                    else\n                        return quest:event(104)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [105] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n\n                [107] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.LEFT_MAP_PIECE)\n                        player:delKeyItem(xi.keyItem.MIDDLE_MAP_PIECE)\n                        player:delKeyItem(xi.keyItem.RIGHT_MAP_PIECE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erik'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.LEFT_MAP_PIECE) then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            ['Gravestone'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.MIDDLE_MAP_PIECE) then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            ['Sarcophagus_map_quest'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.RIGHT_MAP_PIECE) then\n                        return quest:progressEvent(5)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LEFT_MAP_PIECE)\n                end,\n\n                [4] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MIDDLE_MAP_PIECE)\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.RIGHT_MAP_PIECE)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Message_on_the_Winds.lua"]={["Path"]="scripts/quests/crystalWar/Message_on_the_Winds.lua",["SHA256"]="bce385799732000d4e07a00ac7c400f671c0707fe3821c993afdfbfe2bc4cbe2",["Text"]="-----------------------------------\n-- Message on the Wind\n-- !addquest 7 1\n--\n-- Romualdo     - !pos 133 -19 -36 237\n-- Romualdo (S) - !pos 54 -14 141 84\n-- Childerich   - !pos -313 16 -515 89\n-- qm3          - !pos 439 -40 79 89\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.MESSAGE_ON_THE_WINDS)\n\nquest.reward =\n{\n    fame     = 20,\n    fameArea = xi.fameArea.BASTOK,\n    item     = xi.item.SMART_GRENADE,\n}\n\nquest.sections =\n{\n    -- Section: Talk to Romualdo at the Cannonry in the Metalworks (second floor, K-9).\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainLvl() >= 20\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Romualdo'] = quest:progressEvent(952),\n\n            onEventFinish =\n            {\n                [952] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1) -- Quest doesn't appear in log yet\n                end,\n            },\n        },\n    },\n\n    -- Section: Travel to the past and speak to him again, this time in Batallia Downs (S) (I-7).\n    {\n        check = function(player, status, vars)\n            return vars.Prog == 1\n        end,\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Romualdo'] = quest:progressEvent(109),\n\n            onEventFinish =\n            {\n                [109] = function(player, csid, option, npc)\n                    quest:begin(player) -- Quest now appears in log\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Section: Speak with Childerich in Grauberg (S) at the west side of the house at (E-12).\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Romualdo'] = quest:progressEvent(110), -- Optional dialogue\n        },\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Childerich'] = quest:progressEvent(1),\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    -- Check the ??? at J-9.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Childerich'] = quest:progressEvent(2), -- Optional dialogue\n\n            ['qm3'] = quest:progressEvent(3),\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    -- Speak with Childerich.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Childerich'] = quest:progressEvent(4),\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n\n    -- New default text for Childerich\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Childerich'] = quest:progressEvent(5),\n        },\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Romualdo'] = quest:progressEvent(111),\n\n            onEventFinish =\n            {\n                [111] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setVar(player, 'PostCS', 1)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Section: Post quest cutscene with Romualdo\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and quest:getVar(player, 'PostCS') == 1\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Romualdo'] = quest:progressEvent(953),\n\n            onEventFinish =\n            {\n                [953] = function(player, csid, option, npc)\n                    quest:setVar(player, 'PostCS', 2)\n                end,\n            },\n        },\n    },\n\n    -- Post quest cutscene with Childerich\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and quest:getVar(player, 'PostCS') == 2\n        end,\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Childerich'] = quest:progressEvent(6),\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    quest:setVar(player, 'PostCS', 0)\n                    player:addTitle(xi.title.WINDTALKER)\n                end,\n            },\n        },\n    },\n\n    -- New default text for Romualdo (S)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Romualdo'] = quest:event(112):replaceDefault(),\n        },\n    },\n\n    -- New default text for Childerich\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and player:hasTitle(xi.title.WINDTALKER)\n        end,\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['Childerich'] = quest:event(7):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/SCH_AF1_On_Sabbatical.lua"]={["Path"]="scripts/quests/crystalWar/SCH_AF1_On_Sabbatical.lua",["SHA256"]="f03a1118f97d7c3befaf9f9c6b25c68ff6f30622dcbc9a6213aca0e2b553b85c",["Text"]="-----------------------------------\n-- On Sabbatical\n-----------------------------------\n-- !addquest 7 32\n-- Erlene                : !pos 376.936 -39.999 17.914 175\n-- Gentle Tiger          : !pos -203.932 -9.998 2.237 87\n-- Indescript Markings   : !pos -456.707 24.4385 -363.364 90\n-----------------------------------\nlocal pashhowID = zones[xi.zone.PASHHOW_MARSHLANDS_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.ON_SABBATICAL)\n\nquest.reward =\n{\n    item = xi.item.KLIMAFORM_SCHEMA\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:getMainJob() == xi.job.SCH and\n                player:getMainLvl() >= xi.settings.main.AF1_QUEST_LEVEL\n        end,\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(18)\n                end\n            },\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ULBRECHTS_SEALED_LETTER)\n                    quest:begin(player)\n                end,\n            }\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(46)\n                    else\n                        return quest:progressEvent(47)\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [46] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            }\n        },\n\n        [xi.zone.PASHHOW_MARSHLANDS_S] =\n        {\n            ['Indescript_Markings'] =\n            {\n                onTrigger = function(player, npc)\n                    local offset = npc:getID() - pashhowID.npc.INDESCRIPT_MARKINGS_OFFSET\n                    if offset == 0 and quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SCHULTZS_SEALED_LETTER)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            }\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(20)\n                    end\n\n                    return quest:progressEvent(19)\n                end\n            },\n            onEventFinish =\n            {\n                [20] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ULBRECHTS_SEALED_LETTER)\n                        player:delKeyItem(xi.keyItem.SCHULTZS_SEALED_LETTER)\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.ON_SABBATICAL, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.ON_SABBATICAL)\n                    end\n                end,\n            }\n        }\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/SCH_AF2_Downward_Helix.lua"]={["Path"]="scripts/quests/crystalWar/SCH_AF2_Downward_Helix.lua",["SHA256"]="b52cc3d2091ba79db48cda950440a104c567b94cb66cdc16bc529b22c004cb4e",["Text"]="-----------------------------------\n-- Downward Helix\n-----------------------------------\n-- !addquest 7 33\n-- Erlene              : !pos 376.936 -39.999 17.914 175\n-- Indescript Markings : !pos 322 24 113 98\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.DOWNWARD_HELIX)\n\nquest.reward =\n{\n    item = xi.item.SCHOLARS_BRACERS\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.ON_SABBATICAL) and\n                xi.quest.getVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.ON_SABBATICAL, 'Timer') <= VanadielUniqueDay() and\n                player:getMainJob() == xi.job.SCH and\n                player:getMainLvl() >= xi.settings.main.AF2_QUEST_LEVEL\n        end,\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(23)\n                end\n            },\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            }\n        },\n    },\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.EAST_RONFAURE_S and\n                    quest:getVar(player, 'Prog') == 0\n                then\n                    return 65\n                end\n            end,\n\n            onEventFinish =\n            {\n                [65] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            }\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Erlene'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    if questProgress == 1 then\n                        return quest:progressEvent(25)\n                    elseif questProgress == 0 then\n                        return quest:progressEvent(24)\n                    elseif questProgress < 4 then\n                        return quest:progressEvent(26)\n                    else\n                        return quest:progressEvent(27)\n                    end\n                end\n            },\n\n            onEventFinish =\n            {\n                [25] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [27] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.DOWNWARD_HELIX, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.DOWNWARD_HELIX)\n                    end\n                end,\n            }\n        },\n\n        [xi.zone.SAUROMUGUE_CHAMPAIGN_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.ROLANBERRY_FIELDS_S and\n                    quest:getVar(player, 'Prog') == 2\n                then\n                    return 3\n                end\n            end,\n\n            ['Indescript_Markings'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [4] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.ULBRECHTS_MORTARBOARD) then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            }\n        },\n\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/Seeing_Spots.lua"]={["Path"]="scripts/quests/crystalWar/Seeing_Spots.lua",["SHA256"]="c92bb65c953973c1bad00d45c24b8f4a7c3f818a49ac479774ea8a1910b02326",["Text"]="-----------------------------------\n-- Seeing Spots\n-- !addquest 7 10\n-- Wyatt: !pos 124 0 84 80\n-- LADYBUG_WING: !additem 2506\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SEEING_SPOTS)\n\nquest.reward =\n{\n    gil = 3000,\n    title = xi.title.LADY_KILLER,\n}\n\nquest.sections =\n{\n    -- After speaking with Wyatt, collect four Ladybug Wings.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Wyatt'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(2)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Trade the wings to Wyatt to receive your reward.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED or status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Wyatt'] =\n            {\n                -- Reminder\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(3)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { { xi.item.LADYBUG_WING, 4 } }) then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:confirmTrade()\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/The_Dawn_of_Delectability.lua"]={["Path"]="scripts/quests/crystalWar/The_Dawn_of_Delectability.lua",["SHA256"]="c8aa75523b043e5e3e8717142333b470eb4f7417b2755ceb758294c635a8f8aa",["Text"]="-----------------------------------\n-- The Dawn of Delectability\n-- !addquest 7 5\n--\n-- BASTORE_SWEEPER - !additem 5473\n-- PEPPERONI       - !additem 5660\n-- WALNUT          - !additem 5661\n-- DRAGON_FRUIT    - !additem 5662\n--\n-- Ranpi-Monpi (S) - !pos -115 -3 43 94\n-- Ranpi-Monpi     - !pos -116 -3 52 238\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_DAWN_OF_DELECTABILITY)\n\nquest.reward =\n{\n    item = xi.item.TRAINEE_KNIFE,\n}\n\nquest.sections =\n{\n    -- Visit Ranpi-Monpi (S) in Windurst Waters (S) (E-9, north side) to start the quest.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(117),\n\n            onEventFinish =\n            {\n                [117] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Speak with Ranpi in the present and he'll request ingredients\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(119), -- Optional dialogue\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(978),\n\n            onEventFinish =\n            {\n                [978] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Trade Ranpi the ingredients\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ranpi-Monpi'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { xi.item.PEPPERONI, xi.item.WALNUT, xi.item.DRAGON_FRUIT, xi.item.BASTORE_SWEEPER })\n                    then\n                        return quest:progressEvent(983)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(979) -- reminder dialogue\n                end,\n            },\n\n            onEventFinish =\n            {\n                [983] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 3)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n            },\n        },\n    },\n\n    -- Speak with Ranpi before day is up\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3 and\n                quest:getVar(player, 'Timer') > VanadielUniqueDay()\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(982)\n        },\n    },\n\n    -- Speak with Ranpi after a game day wait\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3 and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(980),\n\n            onEventFinish =\n            {\n                [980] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.RANPI_MONPI_SPECIALTY)\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setVar(player, 'Timer', 0)\n                end,\n            },\n        },\n    },\n\n    -- Return to Windurst Waters (S) and feed Ranpi.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(118),\n\n            onEventFinish =\n            {\n                [118] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.RANPI_MONPI_SPECIALTY)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CULINARY_KNIFE)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n\n    -- Return to Windurst Waters and finish the quest\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Ranpi-Monpi'] = quest:progressEvent(981),\n\n            onEventFinish =\n            {\n                [981] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.CULINARY_KNIFE)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- New default text for Ranpi\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED or vars.Prog == 5\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Ranpi-Monpi'] = quest:event(120):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/The_Flipside_of_Things.lua"]={["Path"]="scripts/quests/crystalWar/The_Flipside_of_Things.lua",["SHA256"]="6149f88ebd08ef37ed9562b94bd13c0737ef59e50c570a4ee6f9cb55e061b82e",["Text"]="-----------------------------------\n-- The Flipside of Things\n-----------------------------------\n-- !addquest 7 11\n-- Rarcasmeault : !pos 146.175 -6.000 93.04\n-- _qm2         : !pos -69.588 -1.415 57.695\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_FLIPSIDE_OF_THINGS)\n\nquest.reward =\n{\n    exp     = 2000,\n    gil     = 2000,\n    keyItem = xi.keyItem.MAP_OF_VUNKERL_INLET,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Rarcasmeault'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(6)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [6] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Rarcasmeault'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.FIREPOWER_CASE) then\n                        return quest:progressEvent(9)\n                    else\n                        return quest:event(8) -- This is their default action until the quest is completed.\n                    end\n                end,\n            },\n\n            ['_qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.FIREPOWER_CASE) then\n                        return quest:progressEvent(7)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FIREPOWER_CASE)\n                end,\n\n                [9] = function(player, csid, option, npc)\n                    quest:complete(player)\n                    player:delKeyItem(xi.keyItem.FIREPOWER_CASE)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Rarcasmeault'] = quest:event(4):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"}};
